const resultados={primeiro:{data:'4 de outubro de 2026',validos:'125.272.513',brancos:'2.300.781',brancosPct:'1,84%',nulos:'3.674.149',nulosPct:'2,93%',candidatos:[{nome:'Flávio Bolsonaro',partido:'PL',votos:'56.104.268',pct:'47,03%',status:'1º lugar'},{nome:'Luiz Inácio Lula da Silva',partido:'PT',votos:'53.876.617',pct:'45,16%',status:'2º lugar'}]},segundo:{data:'25 de outubro de 2026',validos:'124.082.273',brancos:'1.430.496',brancosPct:'1,12%',nulos:'2.723.305',nulosPct:'2,12%',candidatos:[{nome:'Luiz Inácio Lula da Silva',partido:'PT',votos:'64.256.232',pct:'51,79%',status:'Reeleito, 1º lugar',destaque:true},{nome:'Flávio Bolsonaro',partido:'PL',votos:'59.826.041',pct:'48,21%',status:'2º lugar'}]}};
const fonte='https://resultados.tse.jus.br';
function turno(titulo,d){return `<article class="resultado-turno"><header><span>${titulo}</span><small>${d.data}</small></header><div class="resultado-candidatos">${d.candidatos.map(c=>`<div class="${c.destaque?'resultado-eleito':''}"><b>${c.status}</b><h5>${c.nome} <small>${c.partido}</small></h5><strong>${c.pct}</strong><p>${c.votos} votos</p></div>`).join('')}</div><footer><span><b>${d.validos}</b> votos válidos</span><span><b>${d.brancos}</b> brancos · ${d.brancosPct}</span><span><b>${d.nulos}</b> nulos · ${d.nulosPct}</span></footer></article>`}
function aplicar(){const raiz=document.querySelector('.eleicoes-2026');if(!raiz||raiz.querySelector('.resultado-eleicao-2026'))return;const alvo=raiz.querySelector('.eleicao-pacotes')||raiz.querySelector('.eleicao-lista');if(!alvo)return;const s=document.createElement('section');s.className='resultado-eleicao-2026';s.innerHTML=`<div class="resultado-titulo"><span class="rotulo">RESULTADO OFICIAL · PRESIDÊNCIA DA REPÚBLICA</span><h4>Um marco histórico.</h4><div class="resultado-editorial"><p>Confesso que é difícil olhar para esse resultado e enxergar apenas números. São <strong>64.256.232 votos</strong>. Mais de 64 milhões de brasileiros que foram às urnas e decidiram que Luiz Inácio Lula da Silva deveria continuar na Presidência da República por mais quatro anos.</p><p>E, para mim, existe algo muito forte nisso.</p><p>Lula venceu em 2002. Venceu novamente em 2006. Voltou e venceu em 2022. E agora, em 2026, aos 80 anos, venceu mais uma vez. É sua quarta vitória em uma eleição presidencial e a segunda consecutiva desde seu retorno à Presidência. Independentemente de qualquer opinião política, isso passa a fazer parte da história eleitoral brasileira.</p><p>Mas aqui também existe a minha opinião. Afinal, esta Biblioteca não foi feita para ser um amontoado de números sem personalidade. Para mim, quando 64.256.232 pessoas escolhem um candidato entre os dois que chegaram ao segundo turno, existe ali uma enorme demonstração de confiança. Eu vejo esse resultado como milhões de brasileiros dizendo, através do voto, em quem confiavam para assumir a responsabilidade de conduzir o país naquele momento.</p><p>Lula terminou com <strong>51,79%</strong> dos votos válidos. Flávio Bolsonaro recebeu <strong>48,21%</strong>. A diferença foi de <strong>4.430.191 votos</strong>.</p><p>Muita gente comemorou. Muita gente não gostou. Outros provavelmente ainda levarão algum tempo para aceitar o resultado. Faz parte. Ninguém é obrigado a gostar de quem venceu uma eleição. Democracia nunca significou unanimidade.</p><p>Mas existe uma coisa que opinião nenhuma altera: as urnas deram a Lula mais quatro anos na Presidência da República.</p><p>E talvez seja justamente por isso que eu quis escrever algo além de uma tabela com porcentagens nesta página.</p><p>Porque eleições viram números muito rápido. 51,79%. 64.256.232 votos. 4.430.191 votos de diferença. Só que, por trás de cada número, existiu uma pessoa fazendo uma escolha.</p><p>No dia 25 de outubro de 2026, milhões fizeram a sua.</p><p class="resultado-fecho"><strong>Lula foi reeleito presidente do Brasil. Venceu sua segunda eleição presidencial consecutiva desde seu retorno e, pela quarta vez em sua trajetória, venceu uma eleição para a Presidência da República.</strong></p><p class="resultado-anos"><strong>2002. 2006. 2022. 2026.</strong></p><p>Quatro vitórias nas urnas, separadas por mais de duas décadas da história do Brasil.</p><p class="resultado-historia"><strong>E isso agora é história.</strong></p></div><div class="resultado-vantagem"><span>DIFERENÇA NO 2º TURNO</span><strong>4.430.191 votos</strong><p>Lula terminou a apuração com 4.430.191 votos a mais: foram 64.256.232 votos para Lula e 59.826.041 para Flávio Bolsonaro.</p></div><p class="resultado-nota">Votação nacional. Os percentuais dos candidatos são calculados sobre os votos válidos.</p></div>${turno('1º TURNO',resultados.primeiro)}${turno('2º TURNO',resultados.segundo)}<a class="resultado-fonte" href="${fonte}" target="_blank" rel="noopener noreferrer">Fonte oficial: Tribunal Superior Eleitoral ↗</a>`;alvo.before(s)}
const css=document.createElement('style');css.textContent=`.resultado-eleicao-2026{margin:28px 0;padding:24px;border:1px solid rgba(197,164,96,.28);background:rgba(7,13,12,.72)}.resultado-titulo h4{font-size:clamp(1.7rem,3.4vw,2.7rem);margin:.35rem 0 1rem}.resultado-editorial{max-width:900px}.resultado-editorial p{font-size:clamp(.96rem,1.55vw,1.08rem);line-height:1.72;opacity:.9;margin:.8rem 0}.resultado-editorial strong{opacity:1}.resultado-fecho{margin-top:1.35rem!important;font-size:clamp(1.05rem,1.8vw,1.22rem)!important}.resultado-anos{font-family:serif;font-size:clamp(1.35rem,3vw,2rem)!important;letter-spacing:.035em;opacity:1!important;margin:1.15rem 0!important}.resultado-historia{font-family:serif;font-size:clamp(1.25rem,2.7vw,1.8rem)!important;opacity:1!important}.resultado-nota{opacity:.66!important}.resultado-vantagem{margin:22px 0 8px;padding:16px 18px;border:1px solid rgba(197,164,96,.22);background:rgba(197,164,96,.055);display:grid;gap:4px;max-width:620px}.resultado-vantagem span{font-size:.68rem;letter-spacing:.14em;opacity:.65}.resultado-vantagem strong{font-family:serif;font-size:clamp(1.55rem,3.5vw,2.35rem);font-weight:500}.resultado-vantagem p{margin:0;font-size:.86rem;line-height:1.5}.resultado-turno{margin-top:20px;border-top:1px solid rgba(255,255,255,.12);padding-top:18px}.resultado-turno>header{display:flex;justify-content:space-between;gap:16px;align-items:end}.resultado-turno>header span{font-weight:800;letter-spacing:.12em}.resultado-turno>header small{opacity:.65}.resultado-candidatos{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:14px 0}.resultado-candidatos>div{padding:18px;border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.025)}.resultado-candidatos>div.resultado-eleito{background:#ff0000;border:2px solid #ff5252;color:#fff;box-shadow:0 0 0 1px rgba(255,255,255,.12) inset,0 16px 46px rgba(255,0,0,.38)}.resultado-candidatos>div.resultado-eleito b,.resultado-candidatos>div.resultado-eleito p,.resultado-candidatos>div.resultado-eleito h5 small{opacity:1;color:#fff}.resultado-candidatos>div.resultado-eleito strong{color:#fff;text-shadow:0 2px 14px rgba(80,0,0,.3)}.resultado-candidatos b{font-size:.72rem;letter-spacing:.08em;opacity:.7}.resultado-candidatos h5{font-size:1.05rem;margin:8px 0}.resultado-candidatos h5 small{font-size:.72rem;opacity:.62}.resultado-candidatos strong{display:block;font-size:clamp(1.7rem,4vw,2.7rem);font-family:serif}.resultado-candidatos p{margin:.2rem 0 0;opacity:.72}.resultado-turno footer{display:flex;flex-wrap:wrap;gap:8px 18px;font-size:.86rem;opacity:.78}.resultado-fonte{display:inline-block;margin-top:20px;text-decoration:underline;text-underline-offset:4px}@media(max-width:650px){.resultado-eleicao-2026{padding:18px 14px}.resultado-candidatos{grid-template-columns:1fr}.resultado-turno>header{align-items:start;flex-direction:column;gap:4px}.resultado-vantagem{padding:14px}.resultado-editorial p{line-height:1.64}}`;document.head.append(css);
new MutationObserver(aplicar).observe(document.body,{childList:true,subtree:true});document.addEventListener('click',e=>{if(e.target.closest?.('[data-obs-aba="eleicoes2026"]'))setTimeout(aplicar,120)});aplicar();